const prs = $input.all();
let summary = `# Weekly Development Summary

## Overview
- **Period:** ${new Date(Date.now() - 7*86400000).toLocaleDateString()} - ${new Date().toLocaleDateString()}
- **Total Merged PRs:** ${prs.length}

## Merged Pull Requests

`;

const categories = { features: [], fixes: [], docs: [], refactors: [], tests: [], other: [] };
for (const pr of prs) {
  const title = pr.json.title;
  const url = pr.json.html_url;
  const author = pr.json.user?.login || 'unknown';
  const date = new Date(pr.json.merged_at).toLocaleDateString();
  const line = `- [${date}] [${title}](${url}) by @${author}`;

  const lower = title.toLowerCase();
  if (lower.match(/^(feat|add|implement|new)/)) categories.features.push(line);
  else if (lower.match(/^(fix|bug|patch|hotfix)/)) categories.fixes.push(line);
  else if (lower.match(/^(docs?|readme)/)) categories.docs.push(line);
  else if (lower.match(/^(refactor|clean|improve)/)) categories.refactors.push(line);
  else if (lower.match(/^(test)/)) categories.tests.push(line);
  else categories.other.push(line);
}

for (const [cat, items] of Object.entries(categories)) {
  if (items.length > 0) {
    summary += `\n### ${cat.charAt(0).toUpperCase() + cat.slice(1)} (${items.length})\n\n${items.join('\n')}\n`;
  }
}

summary += `\n---\n*Generated by n8n + Claude Code Weekly Summary workflow*\n`;
return [{ json: { summary, pr_count: prs.length, categories: Object.fromEntries(Object.entries(categories).map(([k,v]) => [k, v.length])) } }];
